REPLACE INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
	(332, 'ruRU', 'Но знаешь, Сара, если мертвые могут вернуться на Азерот и незримо витать вокруг тех, кого они любили, я всегда буду возле тебя, в самый светлый день и в самую темную ночь, в счастливейшие моменты и в мрачнейшие часы, и если ты ощутишь на своих щеках легкое дуновение ветерка, это будет мое дыхание, а когда ты почувствуешь, как прохладный воздух овевает твой горячий лоб, это будет мой дух.\r\n\r\nСара, не оплакивай меня, как мертвого, думай, что я ушел и жду тебя, ибо мы встретимся снова.\r\n\r\n--Твой Салли', 0),
	(324, 'ruRU', 'Нептулон восстал из океана огромной водяной башней и наслал на обреченный И\'лалай огромных краккенов. Столь огромны были эти твари, что со щупальцев их свисал лес водорослей, и левиафаны проплывали сквозь них.$B$BСамый громадный из краккенов воздел конечности и обрушил их на море, подняв волны. И волны эти яростно устремились к И\'лалаю.', 0),
	(325, 'ruRU', 'Краккены взревели, и голоса их были подобны грому в час бури:$B$B"Мы идем!"$B$BНо Мин\'лот не дрогнул. Он призвал свою магию. Волны, посланные на И\'лалай, расступились, обогнули город и залили джунгли позади него. Затем Мин\'лот велел своим помощникам произнести сковывающие заклинания, и десятки тролльих голосов слились в нестройную песнь.$B$BНо один голос звучал громче остальных.', 0),
	(326, 'ruRU', 'Мин\'лот ревел, его магия вобрала силу заклинаний его помощников, и Мин\'лот направил ее на приближающихся краккенов.$B$BМоре расступилось, и заклинание Мин\'лота устремилось к слугам Нептулона. Молния разорвала небо, и заклинание поразило их, и тысячи огненных стрел рухнули вниз. Вода закипела, дно покрылось кратерами.$B$BМин\'лот торжествующе вскричал, зная, что его заклинание сразит огромных тварей. ', 0),
	(327, 'ruRU', 'Но краккены – древние, очень древние твари. Они помнили времена, когда земля впервые родилась из моря.$B$BОни помнили владычество Древних Богов, они помнили, как явились Титаны и низвергли их. Они помнили времена, когда магия была новой.$B$BОни стары и помнят много тайн. И хотя заклинание Мин\'лота было могущественно, оно, подобно самим троллям, все же было смертным.$B$BИ поэтому оно не сработало.', 0),
	(328, 'ruRU', 'Оно не смогло сковать краккенов, но разъярило их. Много эпох смертные не причиняли им боли, а заклинание троллей оказалось болезненным!$B$BИ вот краккены сбросили оковы заклинания Мин\'лота и взревели от ярости.$B$BРаздался громовой рокот. Из глубин поднялись большие волны и понеслись к суше. Волны достигли И\'лалая и накрыли город тенью.$B$BНо прежде чем уничтожить его, краккены на миг замерли.', 0),
	(329, 'ruRU', 'Тролли-знахари содрогнулись и воззвали к своему владыке. Мин\'лот смотрел на горы, поднявшиеся из моря, обреченный и несгибаемый. Он повернулся к ученикам и прошептал свои последние слова, которые тролли запечатлели в камне. Затем Мин\'лот повернулся к надвигающимся краккенам.$B$BОн нахмурился и метнул в них свой посох. Это было его последнее деяние.$B$BКраккены направили свою ярость на Мин\'лота, и океан обрушился на И\'лалай.$B$BИ его не стало.', 0),
	(330, 'ruRU', 'И воды упали на джунгли, смывая все на своем пути. Тролли и звери кричали от ужаса и муки, пока воды терзали и поглощали их.$B$BМногие Гурубаши гадали, за что океан обрушился на них, но они умерли, так ничего и не узнав.$B$BИ наконец, достигнув гор, воды остановились. Умиротворенные, они вернулись в свои берега, оставляя за собой смерть.$B$BВоды отступили, но И\'лалай они окружили и затопили навсегда.', 0),
	(331, 'ruRU', 'И вождь Вар\'газул, который находился в безопасности за горами, в Зул\'Гурубе, спустился в джунгли и обнаружил, что его народа больше нет.$B$BИ он пришел в отчаяние, так как его мечты о завоеваниях потерпели крах.$B$BА Мин\'лота-Змея так и не нашли.', 0);